const key='bookwiz-v1';
export function loadState(){try{const d=JSON.parse(localStorage.getItem(key));if(d&&Array.isArray(d.projects)&&d.version===1&&d.settings&&typeof d.settings.name==='string'&&Array.isArray(d.connections)&&d.activity&&d.projects.every(p=>p&&typeof p.title==='string'&&Array.isArray(p.chapters)&&p.chapters.every(c=>c&&typeof c.title==='string'&&typeof c.text==='string')))return d;}catch{}return {version:1,projects:seedProjects(),connections:[],activeConnection:null,settings:{name:'Writer',author:'',theme:'night',themePack:'graphite',rememberBookDefaults:true,platform:'auto',reduceTransparency:false,reduceMotion:false,dailyGoal:500,consent:true,font:19},activity:{}};}
export function saveState(state){localStorage.setItem(key,JSON.stringify(state));}
export function validateBackup(d){if(!d||d.version!==1||!Array.isArray(d.projects))throw Error('This file is not a BookWiz backup.');if(d.captureInbox!==undefined&&(!Array.isArray(d.captureInbox)||d.captureInbox.some(n=>!n||typeof n.text!=='string'||n.text.length>20000)))throw Error('The backup contains invalid captured notes.');for(const p of d.projects){if(!p||typeof p.title!=='string'||!Array.isArray(p.chapters)||!p.chapters.length||p.chapters.some(c=>!c||typeof c.title!=='string'||typeof c.text!=='string'))throw Error('The backup contains an incomplete manuscript.');for(const key of ['characters','bible','worlds','notes','references','revisions','proposals','contextChanges']){p[key]??=[];if(!Array.isArray(p[key])||p[key].some(x=>!x||typeof x!=='object'))throw Error('The backup contains invalid story details.');}if(p.worlds.some(w=>typeof w.name!=='string'||typeof w.detail!=='string'||typeof w.id!=='string'))throw Error('The backup contains invalid world groups.');if(p.characters.some(c=>typeof c.name!=='string')||p.bible.some(c=>typeof c.name!=='string'||typeof c.detail!=='string')||p.references.some(r=>typeof r.text!=='string'))throw Error('The backup contains invalid character, world, or reference data.');for(const key of ['author','genre','premise','world','subtitle','language']){if(p[key]!==undefined&&typeof p[key]!=='string')throw Error('The backup contains invalid book metadata.');p[key]??=key==='language'?'English':'';}p.target=Number(p.target)||65000;if(p.image&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(p.image))delete p.image;}return d;}
export const bookMarkdown=p=>manuscriptMarkdown(p);
export const bookTex=p=>bookLaTex(p);
export const coverSvg=(p,back=false)=>bookCoverSVG(p,back);
export const printHTML=p=>printBookHTML(p);
export function download(name,content,type='text/plain'){const blob=content instanceof Blob?content:new Blob([content],{type});if(saveNative(name,blob))return;const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
